1	// Package chainledger implements the on-chain data governance core.
2	package chainledger
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"sort"
8		"strings"
9	)
10	
11	// PlanChange is one record in a lineage adjustment plan: the dataset name and
12	// the complete list of its direct upstreams after the batch is applied.
13	//
14	// A change may name a dataset that does not exist yet (it is registered) or an
15	// existing dataset (its direct upstreams are replaced wholesale). Datasets not
16	// mentioned in the plan keep their current direct upstreams.
17	type PlanChange struct {
18		Name      string   `json:"name"`
19		Upstreams []string `json:"upstreams"`
20	}
21	
22	// Plan is a batch of lineage adjustments read from a JSON file.
23	type Plan struct {
24		Changes []PlanChange `json:"changes"`
25	}
26	
27	// Relation is a directed lineage edge: Upstream -> Downstream, meaning the
28	// downstream dataset derives from the upstream dataset.
29	type Relation struct {
30		Upstream   string `json:"upstream"`
31		Downstream string `json:"downstream"`
32	}
33	
34	// GraphDataset is one dataset record in the on-disk graph JSON.
35	type GraphDataset struct {
36		Name      string   `json:"name"`
37		Upstreams []string `json:"upstreams"`
38	}
39	
40	// GraphFile is the on-disk JSON representation of a lineage graph.
41	type GraphFile struct {
42		Datasets []GraphDataset `json:"datasets"`
43	}
44	
45	// BatchReport is the deterministic report produced by preview and apply.
46	//
47	// All slices are non-nil (empty lists encode as [] in JSON). Datasets and name
48	// lists are sorted by name byte order; relation lists are sorted by upstream
49	// then downstream.
50	type BatchReport struct {
51		FinalGraph           GraphFile  `json:"finalGraph"`
52		NewDatasets          []string   `json:"newDatasets"`
53		ChangedDatasets      []string   `json:"changedDatasets"`
54		AddedRelations       []Relation `json:"addedRelations"`
55		RemovedRelations     []Relation `json:"removedRelations"`
56		AffectedDownstreams  []string   `json:"affectedDownstreams"`
57	}
58	
59	// adjacency maps a dataset name to its sorted, duplicate-free parent names.
60	type adjacency map[string][]string
61	
62	// graphAdjacency derives the parent map from the in-memory graph. It rejects
63	// nil lineage nodes, empty names, and references to upstreams that are not
64	// registered. It does not check for cycles; use validateAcyclic for that.
65	func graphAdjacency(graph map[string]*Lineage) (adjacency, error) {
66		if graph == nil {
67			return nil, fmt.Errorf("%w: create the graph map with make before validating", ErrNotInitialized)
68		}
69		adj := make(adjacency, len(graph))
70		for name, entry := range graph {
71			if entry == nil {
72				return nil, fmt.Errorf("%w: dataset %q points to a nil lineage node", ErrInvalidArgument, name)
73			}
74			if name == "" {
75				return nil, fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
76			}
77			parents := uniqueSorted(entry.Parents)
78			for _, parent := range parents {
79				if _, ok := graph[parent]; !ok {
80					return nil, fmt.Errorf("%w: dataset %q references upstream %q which is not registered", ErrNotFound, name, parent)
81				}
82			}
83			adj[name] = parents
84		}
85		return adj, nil
86	}
87	
88	// ValidateGraph checks the in-memory graph for structural problems: nil nodes,
89	// empty names, missing upstreams, and cycles. It does not mutate the graph.
90	//
91	// A graph that fails validation cannot be used as the basis for a batch: an
92	// adjustment plan must not be allowed to paper over pre-existing corruption.
93	func ValidateGraph(graph map[string]*Lineage) error {
94		adj, err := graphAdjacency(graph)
95		if err != nil {
96			return err
97		}
98		return validateAcyclic(adj)
99	}
100	
101	// validateAcyclic reports an error if the parent adjacency contains a cycle
102	// (including a dataset that depends on itself). The error message names the
103	// datasets involved.
104	func validateAcyclic(adj adjacency) error {
105		const (
106			white = 0
107			gray  = 1
108			black = 2
109		)
110		color := make(map[string]int, len(adj))
111		var stack []string
112	
113		var dfs func(node string) error
114		dfs = func(node string) error {
115			color[node] = gray
116			stack = append(stack, node)
117			for _, parent := range adj[node] {
118				switch color[parent] {
119				case gray:
120					// parent is an ancestor of node in the current DFS path, so
121					// following parent edges from parent leads back to parent.
122					idx := 0
123					for stack[idx] != parent {
124						idx++
125					}
126					cycle := make([]string, 0, len(stack)-idx+1)
127					cycle = append(cycle, stack[idx:]...)
128					cycle = append(cycle, parent)
129					return fmt.Errorf("%w: dependency cycle %s", ErrCycle, strings.Join(cycle, " -> "))
130				case white:
131					if err := dfs(parent); err != nil {
132						return err
133					}
134				}
135			}
136			color[node] = black
137			stack = stack[:len(stack)-1]
138			return nil
139		}
140	
141		// Iterate over a sorted snapshot so the first reported cycle is stable
142		// across runs regardless of map iteration order.
143		names := make([]string, 0, len(adj))
144		for name := range adj {
145			names = append(names, name)
146		}
147		sort.Strings(names)
148		for _, name := range names {
149			if color[name] == white {
150				if err := dfs(name); err != nil {
151					return err
152				}
153			}
154		}
155		return nil
156	}
157	
158	// computeBatch validates the graph and plan, then computes the final adjacency
159	// and the diff report. It does not mutate graph. The returned adjacency is the
160	// graph as it will be after the batch; callers that want to commit it should
161	// pass it to applyAdjacency.
162	func computeBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, adjacency, error) {
163		if err := ValidateGraph(graph); err != nil {
164			return nil, nil, err
165		}
166		original, err := graphAdjacency(graph)
167		if err != nil {
168			return nil, nil, err
169		}
170	
171		// Validate the plan: empty names and duplicate declarations reject the
172		// whole batch, naming the dataset and the reason.
173		declarations := make(map[string]int, len(plan.Changes))
174		for _, change := range plan.Changes {
175			if change.Name == "" {
176				return nil, nil, fmt.Errorf("%w: plan contains a dataset with an empty name", ErrInvalidArgument)
177			}
178			declarations[change.Name]++
179			if declarations[change.Name] > 1 {
180				return nil, nil, fmt.Errorf("%w: dataset %q is declared %d times in the plan", ErrInvalidArgument, change.Name, declarations[change.Name])
181			}
182		}
183	
184		// Build the final adjacency: start from the original parents, replace each
185		// planned dataset's parents with its normalized upstreams.
186		final := make(adjacency, len(original)+len(plan.Changes))
187		for name, parents := range original {
188			final[name] = append([]string(nil), parents...)
189		}
190		var newNames []string
191		var changedNames []string
192		for _, change := range plan.Changes {
193			wanted := uniqueSorted(change.Upstreams)
194			old, existed := original[change.Name]
195			switch {
196			case !existed:
197				newNames = append(newNames, change.Name)
198			case !stringSliceEqual(old, wanted):
199				changedNames = append(changedNames, change.Name)
200			}
201			final[change.Name] = wanted
202		}
203		sort.Strings(newNames)
204		sort.Strings(changedNames)
205	
206		// Every upstream must resolve to a dataset that exists in the FINAL graph
207		// (new datasets may reference each other regardless of plan order).
208		for name, parents := range final {
209			for _, parent := range parents {
210				if _, ok := final[parent]; !ok {
211					return nil, nil, fmt.Errorf("%w: dataset %q references upstream %q which does not exist in the final graph", ErrNotFound, name, parent)
212				}
213			}
214		}
215		// The final graph must be acyclic, judged after all replacements.
216		if err := validateAcyclic(final); err != nil {
217			return nil, nil, err
218		}
219	
220		added, removed := diffRelations(original, final)
221		affected := affectedDownstreams(original, final, newNames, changedNames)
222	
223		report := &BatchReport{
224			FinalGraph:          GraphFile{Datasets: adjacencyToDatasets(final)},
225			NewDatasets:         newNames,
226			ChangedDatasets:      changedNames,
227			AddedRelations:      added,
228			RemovedRelations:    removed,
229			AffectedDownstreams: affected,
230		}
231		// Guarantee non-nil slices so JSON encodes empty lists as [].
232		if report.NewDatasets == nil {
233			report.NewDatasets = []string{}
234		}
235		if report.ChangedDatasets == nil {
236			report.ChangedDatasets = []string{}
237		}
238		if report.AddedRelations == nil {
239			report.AddedRelations = []Relation{}
240		}
241		if report.RemovedRelations == nil {
242			report.RemovedRelations = []Relation{}
243		}
244		if report.AffectedDownstreams == nil {
245			report.AffectedDownstreams = []string{}
246		}
247		return report, final, nil
248	}
249	
250	// PreviewBatch validates the graph and plan and returns the report WITHOUT
251	// mutating graph. Preview and apply for the same graph and plan produce
252	// identical reports.
253	func PreviewBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
254		report, _, err := computeBatch(graph, plan)
255		return report, err
256	}
257	
258	// ApplyBatch validates the plan, applies it to graph, and returns the report.
259	// On rejection, graph is left completely unchanged.
260	func ApplyBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
261		report, final, err := computeBatch(graph, plan)
262		if err != nil {
263			return nil, err
264		}
265		applyAdjacency(graph, final)
266		return report, nil
267	}
268	
269	// applyAdjacency rewrites the in-memory graph to match the final adjacency:
270	// nodes absent from final are removed, parents are replaced, and children are
271	// rebuilt from the parent edges.
272	func applyAdjacency(graph map[string]*Lineage, final adjacency) {
273		for name := range graph {
274			if _, ok := final[name]; !ok {
275				delete(graph, name)
276			}
277		}
278		for name, parents := range final {
279			entry := graph[name]
280			if entry == nil {
281				entry = &Lineage{}
282				graph[name] = entry
283			}
284			entry.Dataset = name
285			entry.Parents = append([]string(nil), parents...)
286			entry.Children = nil
287		}
288		for name, parents := range final {
289			for _, parent := range parents {
290				graph[parent].Children = append(graph[parent].Children, name)
291			}
292		}
293		for name := range graph {
294			graph[name].Children = uniqueSorted(graph[name].Children)
295		}
296	}
297	
298	// diffRelations returns the directed edges present in final but not original
299	// (added) and present in original but not final (removed). Both lists are
300	// sorted by upstream then downstream.
301	func diffRelations(original, final adjacency) (added, removed []Relation) {
302		origEdges := edgeSet(original)
303		finalEdges := edgeSet(final)
304		for e := range finalEdges {
305			if !origEdges[e] {
306				added = append(added, e)
307			}
308		}
309		for e := range origEdges {
310			if !finalEdges[e] {
311				removed = append(removed, e)
312			}
313		}
314		sortRelations(added)
315		sortRelations(removed)
316		return added, removed
317	}
318	
319	// edgeSet collapses the adjacency into a set of upstream->downstream edges.
320	func edgeSet(adj adjacency) map[Relation]bool {
321		set := make(map[Relation]bool)
322		for downstream, parents := range adj {
323			for _, upstream := range parents {
324				set[Relation{Upstream: upstream, Downstream: downstream}] = true
325			}
326		}
327		return set
328	}
329	
330	// sortRelations sorts by upstream then downstream.
331	func sortRelations(rels []Relation) {
332		sort.Slice(rels, func(i, j int) bool {
333			if rels[i].Upstream != rels[j].Upstream {
334				return rels[i].Upstream < rels[j].Upstream
335			}
336			return rels[i].Downstream < rels[j].Downstream
337		})
338	}
339	
340	// affectedDownstreams computes the impact set: starting from the seed datasets
341	// (new or actually changed), follow downstream (children) edges in BOTH the
342	// original and the final graphs. Datasets that are themselves seeds are
343	// excluded from the output; every other reachable dataset is included once.
344	//
345	// Walking both graphs matters when relations are deleted: a dataset that was
346	// reachable downstream before the change (and thus loses a lineage path) is
347	// still affected even if the edge is gone in the final graph.
348	func affectedDownstreams(original, final adjacency, newNames, changedNames []string) []string {
349		seeds := make(map[string]bool, len(newNames)+len(changedNames))
350		for _, name := range newNames {
351			seeds[name] = true
352		}
353		for _, name := range changedNames {
354			seeds[name] = true
355		}
356	
357		origChildren := invertAdjacency(original)
358		finalChildren := invertAdjacency(final)
359	
360		seen := make(map[string]bool)
361		queue := make([]string, 0, len(seeds))
362		for seed := range seeds {
363			queue = append(queue, seed)
364		}
365		for len(queue) > 0 {
366			node := queue[0]
367			queue = queue[1:]
368			for _, child := range origChildren[node] {
369				if !seen[child] {
370					seen[child] = true
371					queue = append(queue, child)
372				}
373			}
374			for _, child := range finalChildren[node] {
375				if !seen[child] {
376					seen[child] = true
377					queue = append(queue, child)
378				}
379			}
380		}
381	
382		out := make([]string, 0, len(seen))
383		for name := range seen {
384			if !seeds[name] {
385				out = append(out, name)
386			}
387		}
388		sort.Strings(out)
389		return out
390	}
391	
392	// invertAdjacency maps each dataset to the datasets that depend on it (its
393	// children), with each child list sorted by name.
394	func invertAdjacency(adj adjacency) map[string][]string {
395		children := make(map[string][]string, len(adj))
396		for name, parents := range adj {
397			for _, parent := range parents {
398				children[parent] = append(children[parent], name)
399			}
400		}
401		for name := range children {
402			sort.Strings(children[name])
403		}
404		return children
405	}
406	
407	// adjacencyToDatasets renders the final adjacency as sorted, JSON-ready
408	// records with non-nil upstream lists.
409	func adjacencyToDatasets(adj adjacency) []GraphDataset {
410		names := make([]string, 0, len(adj))
411		for name := range adj {
412			names = append(names, name)
413		}
414		sort.Strings(names)
415		ds := make([]GraphDataset, 0, len(names))
416		for _, name := range names {
417			parents := adj[name]
418			if parents == nil {
419				parents = []string{}
420			}
421			ds = append(ds, GraphDataset{Name: name, Upstreams: parents})
422		}
423		return ds
424	}
425	
426	// stringSliceEqual reports whether a and b contain the same strings in the
427	// same order. Both are expected to be sorted and duplicate-free.
428	func stringSliceEqual(a, b []string) bool {
429		if len(a) != len(b) {
430			return false
431		}
432		for i := range a {
433			if a[i] != b[i] {
434				return false
435			}
436		}
437		return true
438	}
439	
440	// MarshalGraphFile serializes the in-memory graph to the on-disk JSON format.
441	// The graph must be valid; an invalid graph returns an error.
442	func MarshalGraphFile(graph map[string]*Lineage) ([]byte, error) {
443		adj, err := graphAdjacency(graph)
444		if err != nil {
445			return nil, err
446		}
447		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
448		return json.MarshalIndent(gf, "", "  ")
449	}
450	
451	// UnmarshalGraphFile parses the on-disk graph JSON, rebuilds the in-memory
452	// graph (parents and children), and validates it. A graph that is structurally
453	// invalid (empty names, duplicate datasets, missing upstreams, or cycles) is
454	// rejected so it cannot be used as the basis for a batch.
455	func UnmarshalGraphFile(data []byte) (map[string]*Lineage, error) {
456		var gf GraphFile
457		if err := json.Unmarshal(data, &gf); err != nil {
458			return nil, fmt.Errorf("invalid graph JSON: %w", err)
459		}
460		graph := make(map[string]*Lineage, len(gf.Datasets))
461		for _, ds := range gf.Datasets {
462			if ds.Name == "" {
463				return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
464			}
465			if _, exists := graph[ds.Name]; exists {
466				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
467			}
468			graph[ds.Name] = &Lineage{Dataset: ds.Name, Parents: uniqueSorted(ds.Upstreams)}
469		}
470		// Rebuild children from the parent edges so the in-memory graph is
471		// consistent regardless of how the file was produced.
472		for name, entry := range graph {
473			for _, parent := range entry.Parents {
474				if parentNode, ok := graph[parent]; ok {
475					parentNode.Children = append(parentNode.Children, name)
476				}
477			}
478		}
479		for name := range graph {
480			graph[name].Children = uniqueSorted(graph[name].Children)
481		}
482		if err := ValidateGraph(graph); err != nil {
483			return nil, err
484		}
485		return graph, nil
486	}
487	
488	// UnmarshalPlan parses the plan JSON. The plan structure (empty names,
489	// duplicate declarations) is validated later by computeBatch so that preview
490	// and apply share identical rejection behavior.
491	func UnmarshalPlan(data []byte) (Plan, error) {
492		var p Plan
493		if err := json.Unmarshal(data, &p); err != nil {
494			return p, fmt.Errorf("invalid plan JSON: %w", err)
495		}
496		return p, nil
497	}
