259			t.Errorf("order/duplicate-only change counted as a real change: %v", report.ChangedDatasets)
260		}
261		if len(report.AddedRelations) != 0 || len(report.RemovedRelations) != 0 {
262			t.Errorf("order/duplicate-only change produced a relation diff: +%v -%v", report.AddedRelations, report.RemovedRelations)
263		}
264	}
