266	// TestBatchRejectsInvalidPlan verifies that the whole batch is rejected when a
267	// dataset is declared twice, a name is empty, or an upstream does not exist in
268	// the final graph.
269	func TestBatchRejectsInvalidPlan(t *testing.T) {
270		t.Run("duplicate declaration", func(t *testing.T) {
271			graph := buildGraph(t, P("A"))
272			plan := planOf(change("A"), change("A", "B"))
273			_, err := PreviewBatch(graph, plan)
274			if !errors.Is(err, ErrInvalidArgument) {
275				t.Fatalf("err = %v, want ErrInvalidArgument", err)
276			}
277			if !strings.Contains(err.Error(), "A") {
278				t.Errorf("error %q does not name dataset A", err)
279			}
280		})
281	
282		t.Run("empty name", func(t *testing.T) {
283			graph := buildGraph(t, P("A"))
284			plan := planOf(change(""))
285			_, err := PreviewBatch(graph, plan)
286			if !errors.Is(err, ErrInvalidArgument) {
287				t.Fatalf("err = %v, want ErrInvalidArgument", err)
288			}
289		})
290	
291		t.Run("missing final upstream", func(t *testing.T) {
292			graph := buildGraph(t, P("A"))
293			plan := planOf(change("A", "ghost"))
294			_, err := PreviewBatch(graph, plan)
295			if !errors.Is(err, ErrNotFound) {
296				t.Fatalf("err = %v, want ErrNotFound", err)
297			}
298			if !strings.Contains(err.Error(), "ghost") {
299				t.Errorf("error %q does not name the missing upstream ghost", err)
300			}
301		})
302	
303		t.Run("upstream missing even though declared later in plan", func(t *testing.T) {
304			// B is declared but the plan references a name that is never declared
305			// and never existed in the original graph.
306			graph := buildGraph(t, P("A"))
307			plan := planOf(change("A", "B"), change("B", "nope"))
308			_, err := PreviewBatch(graph, plan)
309			if !errors.Is(err, ErrNotFound) {
310				t.Fatalf("err = %v, want ErrNotFound", err)
311			}
312		})
313	}
